@namespace sv_6ffb6d960b83425884042827440ed6bf.Components.Pages.Apply

<nav aria-label="Application steps" class="step-indicator mb-4">
    <ol class="d-flex list-unstyled justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i;
            var state = step < CurrentStep ? "completed"
                      : step == CurrentStep ? "active"
                      : "future";
            <li class="step-item text-center flex-fill @state"
                role="button"
                @onclick="() => OnStepClick(step)">
                <div class="step-circle mx-auto mb-1 d-flex align-items-center justify-content-center rounded-circle @GetCircleClass(state)">
                    @if (state == "completed")
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@(step + 1)</span>
                    }
                </div>
                <small class="@GetLabelClass(state)">@StepNames[step]</small>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private async Task OnStepClick(int step)
    {
        if (step < CurrentStep)
            await OnStepClicked.InvokeAsync(step);
    }

    private static string GetCircleClass(string state) => state switch
    {
        "completed" => "bg-success text-white",
        "active" => "bg-primary text-white",
        _ => "bg-light text-muted border"
    };

    private static string GetLabelClass(string state) => state switch
    {
        "completed" => "text-success fw-semibold",
        "active" => "text-primary fw-semibold",
        _ => "text-muted"
    };
}

.step-indicator ol {
    counter-reset: step;
}

.step-item {
    position: relative;
    z-index: 1;
}

.step-circle {
    width: 36px;
    height: 36px;
    font-size: 0.9rem;
    font-weight: bold;
    transition: background-color 0.2s;
}

.step-item.completed {
    cursor: pointer;
}

.step-item.future {
    cursor: default;
}

@namespace sv_6ffb6d960b83425884042827440ed6bf.Components.Pages.Apply
@using sv_6ffb6d960b83425884042827440ed6bf.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input class="form-control" @bind="Reference.Name" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input class="form-control" @bind="Reference.Relationship" @bind:event="oninput" />
